#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s[2];
    cin >> s[0] >> s[1];

    int n = s[0].size();
    const int NEG = -1e9;

    vector<int> blocked(n, 0);
    for (int i = 0; i < n; ++i) {
        if (s[0][i] != '0') blocked[i] |= 1;
        if (s[1][i] != '0') blocked[i] |= 2;
    }

    vector<int> dp(4, NEG);
    dp[0] = 0;

    const int shapes[] = {7, 11, 13, 14};

    for (int i = 0; i + 1 < n; ++i) {
        vector<int> next(4, NEG);

        for (int mask = 0; mask < 4; ++mask) {
            if (dp[mask] == NEG || (mask & blocked[i])) continue;

            next[0] = max(next[0], dp[mask]);

            for (int shape : shapes) {
                int currentMask = shape & 3;
                int nextMask = (shape >> 2) & 3;

                if ((currentMask & (mask | blocked[i])) == 0 &&
                    (nextMask & blocked[i + 1]) == 0) {
                    next[nextMask] = max(next[nextMask], dp[mask] + 1);
                }
            }
        }

        dp.swap(next);
    }

    cout << *max_element(dp.begin(), dp.end());
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s[2];
    cin >> s[0] >> s[1];

    const int n = s[0].size();
    const int NEG = -1e9;

    vector<int> dp(4, NEG), nextDp(4, NEG);
    dp[0] = 0;

    for (int col = 0; col < n; ++col) {
        fill(nextDp.begin(), nextDp.end(), NEG);

        int blockedCurrent = 0;
        for (int row = 0; row < 2; ++row)
            if (s[row][col] != '0')
                blockedCurrent |= 1 << row;

        int blockedNext = 0;
        if (col + 1 < n) {
            for (int row = 0; row < 2; ++row)
                if (s[row][col + 1] != '0')
                    blockedNext |= 1 << row;
        }

        for (int mask = 0; mask < 4; ++mask) {
            if (dp[mask] == NEG || (mask & blockedCurrent))
                continue;

            nextDp[0] = max(nextDp[0], dp[mask]);

            if (col + 1 == n)
                continue;

            int unavailable = mask | blockedCurrent | (blockedNext << 2);

            for (int omitted = 0; omitted < 4; ++omitted) {
                int shape = 15 ^ (1 << omitted);
                if ((shape & unavailable) == 0) {
                    int nextMask = (shape >> 2) & 3;
                    nextDp[nextMask] = max(nextDp[nextMask], dp[mask] + 1);
                }
            }
        }

        dp.swap(nextDp);
    }

    cout << *max_element(dp.begin(), dp.end());
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s[2];
    cin >> s[0] >> s[1];

    int n = s[0].size();
    const int NEG = -1e9;

    vector<array<int, 4>> dp(n + 1);
    for (auto& state : dp) state.fill(NEG);
    dp[0][0] = 0;

    const pair<int, int> shapes[] = {
        {1, 3}, {2, 3}, {3, 1}, {3, 2}
    };

    for (int i = 0; i < n; ++i) {
        int blockedCurrent =
            (s[0][i] != '0' ? 1 : 0) |
            (s[1][i] != '0' ? 2 : 0);

        int blockedNext = 3;
        if (i + 1 < n) {
            blockedNext =
                (s[0][i + 1] != '0' ? 1 : 0) |
                (s[1][i + 1] != '0' ? 2 : 0);
        }

        for (int incoming = 0; incoming < 4; ++incoming) {
            if (dp[i][incoming] == NEG) continue;
            if (incoming & blockedCurrent) continue;

            dp[i + 1][0] = max(dp[i + 1][0], dp[i][incoming]);

            if (i + 1 == n) continue;

            for (auto [currentMask, nextMask] : shapes) {
                if (currentMask & (incoming | blockedCurrent)) continue;
                if (nextMask & blockedNext) continue;

                dp[i + 1][nextMask] =
                    max(dp[i + 1][nextMask], dp[i][incoming] + 1);
            }
        }
    }

    cout << dp[n][0];
    return 0;
}

